def dns_lookup(records: dict, domain: str):
    path = []
    visited = set()
    current = domain

    while current and len(path) < 10:
        if current in visited:
            return 'NXDOMAIN'
        visited.add(current)

        if current not in records:
            return 'NXDOMAIN'

        path.append(current)
        record = records[current]

        if record['type'] == 'A':
            return {'ip': record['value'], 'path': path}
        elif record['type'] == 'CNAME':
            current = record['value']

    return 'NXDOMAIN'

solution.javascript:
function dnsLookup(records, domain) {
  const path = [];
  const visited = new Set();
  let current = domain;

  while (current && path.length < 10) {
    if (visited.has(current)) return 'NXDOMAIN';
    visited.add(current);

    if (!(current in records)) return 'NXDOMAIN';

    path.push(current);
    const record = records[current];

    if (record.type === 'A') {
      return { ip: record.value, path };
    } else if (record.type === 'CNAME') {
      current = record.value;
    }
  }

  return 'NXDOMAIN';
}
